var deck = root.querySelector('.mtc-flip-stack-deck');
var cards = Array.prototype.slice.call(root.querySelectorAll('.mtc-flip-stack-card'));
var dots = Array.prototype.slice.call(root.querySelectorAll('.mtc-flip-stack-dot'));
var navs = Array.prototype.slice.call(root.querySelectorAll('.mtc-flip-stack-nav'));
var count = root.querySelector('.mtc-flip-stack-count');
var n = cards.length, cur = 0;
function render() {
  cards.forEach(function (c, i) {
    var rel = i - cur, t, o;
    if (rel < 0) { t = 'translate3d(-48%,-8%,0) rotateY(-74deg) rotateZ(-7deg)'; o = 0; }
    else if (rel > 2) { t = 'translate3d(0,-26px,0) scale(.85)'; o = 0; }
    else { t = 'translate3d(0,' + (-rel * 9) + 'px,0) scale(' + (1 - rel * 0.05) + ')'; o = rel === 0 ? 1 : 0.5; }
    c.style.transform = t;
    c.style.opacity = String(o);
    c.style.zIndex = String(rel < 0 ? n + 6 + rel : n - rel);
    c.style.filter = rel === 0 ? 'none' : 'blur(1.2px)';
    c.style.pointerEvents = rel === 0 ? 'auto' : 'none';
    c.setAttribute('aria-hidden', rel === 0 ? 'false' : 'true');
  });
  dots.forEach(function (d, i) { d.classList.toggle('mtc-flip-stack-dot-on', i === cur); });
  count.textContent = (cur + 1) + ' / ' + n;
  navs.forEach(function (b) {
    var d = Number(b.getAttribute('data-dir'));
    b.disabled = cur + d < 0 || cur + d > n - 1;
  });
}
function go(d) {
  var next = cur + d;
  if (next < 0 || next > n - 1) return;
  cur = next;
  render();
}
navs.forEach(function (b) {
  b.addEventListener('click', function () { go(Number(b.getAttribute('data-dir'))); });
});
deck.addEventListener('click', function () { go(cur === n - 1 ? -(n - 1) : 1); });
root.addEventListener('keydown', function (e) {
  if (e.key === 'ArrowRight') { e.preventDefault(); go(1); }
  else if (e.key === 'ArrowLeft') { e.preventDefault(); go(-1); }
});
render();

