var stage = root.querySelector('.mtc-swipe-deck-stage');
var left = root.querySelector('.mtc-swipe-deck-left');
var undoBtn = root.querySelector('.mtc-swipe-deck-btn-undo');
var keepBtn = root.querySelector('.mtc-swipe-deck-btn-keep');
var skipBtn = root.querySelector('.mtc-swipe-deck-btn-skip');
var all = Array.prototype.slice.call(root.querySelectorAll('.mtc-swipe-deck-card'));
var live = all.slice(), gone = [], drag = null, x0 = 0, dx = 0;
function layout() {
  all.forEach(function (c) { c.style.display = 'none'; });
  live.forEach(function (c, i) {
    if (i > 2) return;
    c.style.display = '';
    c.style.transition = '';
    c.style.zIndex = String(20 - i);
    c.style.opacity = '1';
    c.style.transform = 'translate3d(0,' + i * 7 + 'px,0) scale(' + (1 - i * 0.04) + ')';
    c.style.setProperty('--msd-k', '0');
    c.style.setProperty('--msd-s', '0');
    c.style.pointerEvents = i === 0 ? 'auto' : 'none';
    c.setAttribute('aria-hidden', i === 0 ? 'false' : 'true');
  });
  left.textContent = live.length === 1 ? '1 thread' : live.length + ' threads';
  root.classList.toggle('mtc-swipe-deck-done', live.length === 0);
  undoBtn.disabled = gone.length === 0;
  keepBtn.disabled = live.length === 0;
  skipBtn.disabled = live.length === 0;
}
function fling(dir) {
  var c = live[0];
  if (!c) return;
  live.shift();
  gone.push(c);
  c.style.zIndex = '30';
  c.style.transition = 'transform .45s cubic-bezier(.3,.7,.3,1),opacity .4s ease';
  c.style.transform = 'translate3d(' + dir * 150 + '%,10px,0) rotate(' + dir * 17 + 'deg)';
  c.style.opacity = '0';
  c.style.setProperty(dir > 0 ? '--msd-k' : '--msd-s', '1');
  c.style.pointerEvents = 'none';
  layout();
}
function undo() {
  var c = gone.pop();
  if (!c) return;
  live.unshift(c);
  c.style.display = '';
  layout();
}
stage.addEventListener('pointerdown', function (e) {
  var c = live[0];
  if (!c || !c.contains(e.target)) return;
  drag = c; x0 = e.clientX; dx = 0;
  c.style.transition = 'none';
  c.setPointerCapture(e.pointerId);
});
stage.addEventListener('pointermove', function (e) {
  if (!drag) return;
  dx = e.clientX - x0;
  drag.style.transform = 'translate3d(' + dx + 'px,0,0) rotate(' + dx * 0.05 + 'deg)';
  drag.style.setProperty('--msd-k', String(Math.max(0, Math.min(1, dx / 80))));
  drag.style.setProperty('--msd-s', String(Math.max(0, Math.min(1, -dx / 80))));
});
function release() {
  if (!drag) return;
  var c = drag, d = dx;
  drag = null;
  c.style.transition = '';
  if (Math.abs(d) > 72) fling(d > 0 ? 1 : -1); else layout();
}
stage.addEventListener('pointerup', release);
stage.addEventListener('pointercancel', release);
stage.addEventListener('keydown', function (e) {
  if (e.key === 'ArrowRight') { e.preventDefault(); fling(1); }
  else if (e.key === 'ArrowLeft') { e.preventDefault(); fling(-1); }
  else if (e.key === 'Backspace') { e.preventDefault(); undo(); }
});
keepBtn.addEventListener('click', function () { fling(1); });
skipBtn.addEventListener('click', function () { fling(-1); });
undoBtn.addEventListener('click', undo);
layout();

