var card = root.querySelector('.mtc-tilt-magnet-card');
var cta = root.querySelector('.mtc-tilt-magnet-cta');
var calm = root.ownerDocument.defaultView.matchMedia('(prefers-reduced-motion: reduce)');
var tx = 0, ty = 0, cx = 0, cy = 0, mtx = 0, mty = 0, mcx = 0, mcy = 0;
var over = false, raf = 0;
function tick() {
  if (!root.isConnected) { raf = 0; return; }
  cx += (tx - cx) * 0.14;
  cy += (ty - cy) * 0.14;
  mcx += (mtx - mcx) * 0.18;
  mcy += (mty - mcy) * 0.18;
  card.style.setProperty('--mtm-rx', (-cy * 8).toFixed(2) + 'deg');
  card.style.setProperty('--mtm-ry', (cx * 10).toFixed(2) + 'deg');
  card.style.setProperty('--mtm-tz', (over ? 14 : 0) + 'px');
  card.style.setProperty('--mtm-gx', (50 + cx * 42).toFixed(1) + '%');
  card.style.setProperty('--mtm-gy', (50 + cy * 42).toFixed(1) + '%');
  card.style.setProperty('--mtm-go', over ? '1' : '0');
  cta.style.transform = 'translate3d(' + mcx.toFixed(2) + 'px,' + mcy.toFixed(2) + 'px,0)';
  var rest = Math.abs(tx - cx) + Math.abs(ty - cy) + Math.abs(mtx - mcx) + Math.abs(mty - mcy);
  if (over || rest > 0.002) raf = requestAnimationFrame(tick); else raf = 0;
}
function wake() { if (!raf) raf = requestAnimationFrame(tick); }
card.addEventListener('pointermove', function (e) {
  if (calm.matches) return;
  var r = card.getBoundingClientRect();
  over = true;
  tx = (e.clientX - r.left) / r.width * 2 - 1;
  ty = (e.clientY - r.top) / r.height * 2 - 1;
  var b = cta.getBoundingClientRect();
  var dx = e.clientX - (b.left + b.width / 2);
  var dy = e.clientY - (b.top + b.height / 2);
  var d = Math.sqrt(dx * dx + dy * dy);
  if (d < 110) { mtx = Math.max(-14, Math.min(14, dx * 0.24)); mty = Math.max(-9, Math.min(9, dy * 0.3)); }
  else { mtx = 0; mty = 0; }
  wake();
});
card.addEventListener('pointerleave', function () {
  over = false; tx = 0; ty = 0; mtx = 0; mty = 0;
  wake();
});
cta.addEventListener('focus', function () { over = true; tx = 0.35; ty = -0.35; wake(); });
cta.addEventListener('blur', function () { over = false; tx = 0; ty = 0; wake(); });

