var scene = root.querySelector('.mtc-parallax-poster-scene');
var layers = Array.prototype.slice.call(root.querySelectorAll('[data-d]'));
var calm = root.ownerDocument.defaultView.matchMedia('(prefers-reduced-motion: reduce)');
var spin = root.querySelector('.mtc-parallax-poster-ring');
function move(nx, ny) {
  if (calm.matches) return;
  layers.forEach(function (el) {
    var d = Number(el.getAttribute('data-d')) || 0;
    var t = 'translate3d(' + (nx * d).toFixed(2) + 'px,' + (ny * d * 0.5).toFixed(2) + 'px,0)';
    if (el === spin) el.style.translate = (nx * d).toFixed(2) + 'px ' + (ny * d * 0.5).toFixed(2) + 'px';
    else el.style.transform = t;
  });
  scene.style.setProperty('--mpp-x', (50 - nx * 26).toFixed(1) + '%');
  scene.style.setProperty('--mpp-y', (50 - ny * 26).toFixed(1) + '%');
}
scene.addEventListener('pointermove', function (e) {
  var r = scene.getBoundingClientRect();
  move(-((e.clientX - r.left) / r.width * 2 - 1), -((e.clientY - r.top) / r.height * 2 - 1));
});
scene.addEventListener('pointerleave', function () { move(0, 0); });
scene.addEventListener('focus', function () { move(-0.35, -0.3); });
scene.addEventListener('blur', function () { move(0, 0); });

