var stack = root.querySelector('.mtc-shuffle-stack-stack');
var auto = root.querySelector('.mtc-shuffle-stack-auto');
var order = Array.prototype.slice.call(root.querySelectorAll('.mtc-shuffle-stack-card'));
var busy = false, timer = 0;
function layout() {
  order.forEach(function (c, i) {
    c.style.transform = 'translate3d(0,' + i * -12 + 'px,0) scale(' + (1 - i * 0.035) + ')';
    c.style.filter = i === 0 ? 'none' : 'brightness(' + (1 - i * 0.16).toFixed(2) + ')';
    c.style.zIndex = String(10 - i);
    c.style.pointerEvents = i === 0 ? 'auto' : 'none';
    c.tabIndex = i === 0 ? 0 : -1;
    c.setAttribute('aria-hidden', i === 0 ? 'false' : 'true');
  });
}
function shuffle() {
  if (busy || order.length < 2) return;
  busy = true;
  var c = order[0], settled = false, drop, guard;
  c.style.zIndex = '20';
  c.classList.add('mtc-shuffle-stack-toss');
  function finish() {
    if (settled) return;
    settled = true;
    clearTimeout(drop);
    clearTimeout(guard);
    c.removeEventListener('animationend', finish);
    order.push(order.shift());
    layout();
    c.classList.remove('mtc-shuffle-stack-toss');
    busy = false;
  }
  drop = setTimeout(function () { c.style.zIndex = '1'; }, 340);
  guard = setTimeout(finish, 1100);
  c.addEventListener('animationend', finish);
}
stack.addEventListener('click', function (e) {
  var c = e.target.closest('.mtc-shuffle-stack-card');
  if (c && c === order[0]) shuffle();
});
auto.addEventListener('click', function () {
  var on = auto.getAttribute('aria-pressed') !== 'true';
  auto.setAttribute('aria-pressed', on ? 'true' : 'false');
  if (timer) { clearInterval(timer); timer = 0; }
  if (on) {
    timer = setInterval(function () {
      if (!root.isConnected) { clearInterval(timer); timer = 0; return; }
      shuffle();
    }, 2200);
  }
});
layout();

