.mtc-accordion-card-p{margin:0 0 7px;font-size:11px;line-height:1.55;color:#8d94a3;}
.mtc-accordion-card-meta{display:inline-block;padding:2px 7px;border-radius:5px;border:1px solid rgba(255,255,255,.12);font-family:ui-monospace,Menlo,monospace;font-size:9px;letter-spacing:.06em;color:#767d8c;}
@media (prefers-reduced-motion: reduce){
.mtc-accordion-card-panel{transition:none;}
.mtc-accordion-card-thumb{transition:opacity .12s linear;}
.mtc-accordion-card-plus{transition:none;}
.mtc-accordion-card-inner{transition:opacity .12s linear;transform:none;}
.mtc-accordion-card-on .mtc-accordion-card-inner{transform:none;}
}

