var items = Array.prototype.slice.call(root.querySelectorAll('.mtc-accordion-card-item'));
var btns = Array.prototype.slice.call(root.querySelectorAll('.mtc-accordion-card-btn'));
var thumb = root.querySelector('.mtc-accordion-card-thumb');
var cur = -1;
items.forEach(function (it, i) {
  var panel = it.querySelector('.mtc-accordion-card-panel');
  var id = 'mtc-accordion-card-p' + i + Math.random().toString(36).slice(2, 7);
  panel.id = id;
  panel.setAttribute('role', 'region');
  btns[i].setAttribute('aria-controls', id);
});
function open(i) {
  cur = cur === i ? -1 : i;
  items.forEach(function (it, j) {
    var on = j === cur;
    var panel = it.querySelector('.mtc-accordion-card-panel');
    var inner = it.querySelector('.mtc-accordion-card-inner');
    it.classList.toggle('mtc-accordion-card-on', on);
    btns[j].setAttribute('aria-expanded', on ? 'true' : 'false');
    panel.style.height = on ? inner.offsetHeight + 'px' : '0px';
  });
  root.classList.toggle('mtc-accordion-card-lit', cur > -1);
  if (cur > -1) {
    thumb.style.height = btns[cur].offsetHeight + 'px';
    thumb.style.transform = 'translate3d(0,' + items[cur].offsetTop + 'px,0)';
  }
}
btns.forEach(function (b, i) {
  b.addEventListener('click', function () { open(i); });
  b.addEventListener('keydown', function (e) {
    var to = -1;
    if (e.key === 'ArrowDown') to = (i + 1) % btns.length;
    else if (e.key === 'ArrowUp') to = (i - 1 + btns.length) % btns.length;
    else if (e.key === 'Home') to = 0;
    else if (e.key === 'End') to = btns.length - 1;
    if (to > -1) { e.preventDefault(); btns[to].focus(); }
  });
});
open(0);
